(5456442, 785892, 97814, '<td valign="top">Stunning - love the colour!</td>', 'Stunning - love the colour!', '2009-04-29 01:38:35.000000', NULL, 1),
(5456444, 785951, 44025, '<td valign="top">curious about the image details</td>', 'curious about the image details', '2009-04-29 01:39:32.000000', NULL, 1),
(5456446, 786179, 34547, '<td valign="top">I love the patterns here and I like the square crop. It could be a nice print on a Japanese dress. One of my fav''s so far. Good luck!</td>', 'I love the patterns here and I like the square crop. It could be a nice print on a Japanese dress. One of my fav''s so far. Good luck!', '2009-04-29 01:39:48.000000', NULL, 1),
(5456452, 784771, 46918, '<td valign="top">I really love the colors in this pic....Good job and good luck.</td>', 'I really love the colors in this pic....Good job and good luck.', '2009-04-29 01:41:16.000000', NULL, 1),
(5456468, 785688, 90624, '<td valign="top">Very Nice!</td>', 'Very Nice!', '2009-04-29 01:44:02.000000', NULL, 1),
(5456469, 785103, 34547, '<td valign="top">At first I found the steep angle a bit much but I must admit that my first impression with the colors and textures was, "Wow!" I wondered if the angle actually made the photo less interesting but as I stare at it with my neck bent out of shape, I think you might have actually improved an otherwise average scene. It certainly made me think about my vote. Too bad about the fencing up on the hill or whatever it is.  Good luck!</td>', 'At first I found the steep angle a bit much but I must admit that my first impression with the colors and textures was, "Wow!" I wondered if the angle actually made the photo less interesting but as I stare at it with my neck bent out of shape, I think you might have actually improved an otherwise average scene. It certainly made me think about my vote. Too bad about the fencing up on the hill or whatever it is.  Good luck!', '2009-04-29 01:44:18.000000', NULL, 1),
(5456470, 785982, 34547, '<td valign="top">Love the tone you went with. Interesting tree.</td>', 'Love the tone you went with. Interesting tree.', '2009-04-29 01:45:07.000000', NULL, 1),
