(5458630, 786290, 70128, '<td valign="top">Good point!</td>', 'Good point!', '2009-04-30 10:50:00.000000', NULL, 1),
(5458645, 786295, 70128, '<td valign="top">Some may complain there''s a lot of white in this picture, but i love the perspective and composition. it''s a picture that makes me just stare at it as if i was looking into space</td>', 'Some may complain there''s a lot of white in this picture, but i love the perspective and composition. it''s a picture that makes me just stare at it as if i was looking into space', '2009-04-30 11:03:37.000000', NULL, 1),
(5458647, 786253, 70128, '<td valign="top">Very nice! this could be a postcard</td>', 'Very nice! this could be a postcard', '2009-04-30 11:04:41.000000', NULL, 1),
(5458651, 785068, 70128, '<td valign="top">Another relaxing photograph. very well executed, good composition and colors. soothing shot. 9</td>', 'Another relaxing photograph. very well executed, good composition and colors. soothing shot. 9', '2009-04-30 11:07:23.000000', NULL, 1),
(5458663, 785706, 1569, '<td valign="top">Bamboo is in the grass family of plants.</td>', 'Bamboo is in the grass family of plants.', '2009-04-30 11:13:28.000000', NULL, 1),
(5458665, 786011, 1569, '<td valign="top">This is a nice pix, but I think the composition of the pix lends it more to a square crop than a tall vertical crop.</td>', 'This is a nice pix, but I think the composition of the pix lends it more to a square crop than a tall vertical crop.', '2009-04-30 11:16:07.000000', NULL, 1),
(5458668, 785713, 70128, '<td valign="top">hmm, this looks as if it had been taken with an old 60''s color camera. It''s also OOF, over saturated, needs some color balance editing, and some noise color reduction. I am not rating it, I don''t like giving very low scores because I don''t really "qualify" to be a judge, but I just wanted to give you a constructive criticism of your shot. Maybe you did it on purpose, who knows!? :)</td>', 'hmm, this looks as if it had been taken with an old 60''s color camera. It''s also OOF, over saturated, needs some color balance editing, and some noise color reduction. I am not rating it, I don''t like giving very low scores because I don''t really "qualify" to be a judge, but I just wanted to give you a constructive criticism of your shot. Maybe you did it on purpose, who knows!? :)', '2009-04-30 11:22:26.000000', NULL, 1),
(5458669, 786301, 1569, '<td valign="top">This is a great pix, but straight B/W or just a tiny hint of sepia would have been nicer. Just my opinion. An 8.</td>', 'This is a great pix, but straight B/W or just a tiny hint of sepia would have been nicer. Just my opinion. An 8.', '2009-04-30 11:22:35.000000', NULL, 1),
(5458671, 786075, 70128, '<td valign="top">It''s all out of focus, it''s all baby so unclear. Oops, that sounds like a song, doesn''t it!? :)</td>', 'It''s all out of focus, it''s all baby so unclear. Oops, that sounds like a song, doesn''t it!? :)', '2009-04-30 11:24:40.000000', NULL, 1),
(5458675, 786116, 1569, '<td valign="top">Nice picture--just a bit more depth of field would have made this one better.</td>', 'Nice picture--just a bit more depth of field would have made this one better.', '2009-04-30 11:26:05.000000', NULL, 1),
(5458676, 786079, 70128, '<td valign="top">hey, that right part of the trunk looks like a hand pointing up to the sky!</td>', 'hey, that right part of the trunk looks like a hand pointing up to the sky!', '2009-04-30 11:26:44.000000', NULL, 1),
(5458679, 784749, 70128, '<td valign="top">I like the effect on the branches. How is that achieved?</td>', 'I like the effect on the branches. How is that achieved?', '2009-04-30 11:27:42.000000', NULL, 1),
