(5458693, 786294, 1569, '<td valign="top">Very nice use of soft focus,almost looks like a painting. A 9.</td>', 'Very nice use of soft focus,almost looks like a painting. A 9.', '2009-04-30 11:37:45.000000', NULL, 1),
(5458697, 786216, 1569, '<td valign="top">Spectacular photo!!! Just a touch more sharpening. A 9.</td>', 'Spectacular photo!!! Just a touch more sharpening. A 9.', '2009-04-30 11:45:08.000000', NULL, 1),
(5458701, 786053, 96755, '<td valign="top">Nice colors, scene and exposure.  Very nice photo.</td>', 'Nice colors, scene and exposure.  Very nice photo.', '2009-04-30 11:53:51.000000', NULL, 1),
(5458713, 785908, 96755, '<td valign="top">Nice photo, but the attaention seems more on the sky then the trees.</td>', 'Nice photo, but the attaention seems more on the sky then the trees.', '2009-04-30 11:58:45.000000', NULL, 1),
