(5459885, 786300, 63499, '<td valign="top">Coming back to comment - Nice focus, color and lighting. The low light areas on the trunks seem to be a little too dark - they have very little detail.</td>', 'Coming back to comment - Nice focus, color and lighting. The low light areas on the trunks seem to be a little too dark - they have very little detail.', '2009-05-01 00:15:02.000000', NULL, 1),
(5459898, 786125, 63499, '<td valign="top">Coming back to comment - The focus and color on the blossoms looks good. They are over exposed though and have lost some details in the highlights.</td>', 'Coming back to comment - The focus and color on the blossoms looks good. They are over exposed though and have lost some details in the highlights.', '2009-05-01 00:23:16.000000', NULL, 1),
(5459924, 785713, 63499, '<td valign="top">I like how the tree fills up a lot of the photo and that you didn''t over expose the sky. Overall, your photo looks like it might be a little out of focus, over sharpened and over saturated in color.</td>', 'I like how the tree fills up a lot of the photo and that you didn''t over expose the sky. Overall, your photo looks like it might be a little out of focus, over sharpened and over saturated in color.', '2009-05-01 00:36:03.000000', NULL, 1),
