(5462760, 786253, 100831, '<td valign="top">almost an abstract - in fact I might also have liked it without the grass (reality) in the back. The reflection is terrific!! 7</td>', 'almost an abstract - in fact I might also have liked it without the grass (reality) in the back. The reflection is terrific!! 7', '2009-05-02 00:43:03.000000', NULL, 1),
(5462762, 786183, 100831, '<td valign="top">I love this!! The color, the dof, the details, the directional pulls of the foreground vs background. It''s really wonderful. 9</td>', 'I love this!! The color, the dof, the details, the directional pulls of the foreground vs background. It''s really wonderful. 9', '2009-05-02 00:44:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5462966, 786200, 105708, '<td valign="top">Fisheye really brings the life outta the tree, doesn''t it. I like it.</td>', 'Fisheye really brings the life outta the tree, doesn''t it. I like it.', '2009-05-02 04:21:24.000000', NULL, 1),
(5462977, 786218, 105708, '<td valign="top">The more I look at this, the more I like it.</td>', 'The more I look at this, the more I like it.', '2009-05-02 04:26:03.000000', NULL, 1),
(5462991, 785121, 105708, '<td valign="top">Bottle trees are cool. This is a great tree. Good job with the colours, particularly the sky!</td>', 'Bottle trees are cool. This is a great tree. Good job with the colours, particularly the sky!', '2009-05-02 04:37:15.000000', NULL, 1),
(5463309, 785440, 105113, '<td valign="top">Nice but not captivating. Tree does not stand out.</td>', 'Nice but not captivating. Tree does not stand out.', '2009-05-02 10:13:06.000000', NULL, 1),
(5463313, 786171, 105113, '<td valign="top">I like the colors of the water, beach, and the greens. Tree is a little out of focus on the ends - I suspect due to a breeze.</td>', 'I like the colors of the water, beach, and the greens. Tree is a little out of focus on the ends - I suspect due to a breeze.', '2009-05-02 10:13:49.000000', NULL, 1),
(5463319, 786018, 105113, '<td valign="top">Nice textures on tree, but lighting makes picture dull.</td>', 'Nice textures on tree, but lighting makes picture dull.', '2009-05-02 10:14:42.000000', NULL, 1),
(5463321, 786210, 105113, '<td valign="top">Unique perspective. Like the textures.</td>', 'Unique perspective. Like the textures.', '2009-05-02 10:15:06.000000', NULL, 1),
(5463327, 784775, 105113, '<td valign="top">Colors suit the mood. Would have liked to see the full spread of the tree.</td>', 'Colors suit the mood. Would have liked to see the full spread of the tree.', '2009-05-02 10:16:25.000000', NULL, 1),
(5463333, 785119, 105113, '<td valign="top">The composition of the picture is nice. I don''t feel like the tree is your main subject in this photo.</td>', 'The composition of the picture is nice. I don''t feel like the tree is your main subject in this photo.', '2009-05-02 10:18:24.000000', NULL, 1),
(5463338, 785103, 105113, '<td valign="top">Unique perspective. I''m not sure I like the angle or not, can''t decide. But I do like the gentle colors and the clouds in the sky.</td>', 'Unique perspective. I''m not sure I like the angle or not, can''t decide. But I do like the gentle colors and the clouds in the sky.', '2009-05-02 10:19:37.000000', NULL, 1),
(5463341, 785912, 105113, '<td valign="top">I like the backlighting, and the couple make a strong focus point for the eyes.</td>', 'I like the backlighting, and the couple make a strong focus point for the eyes.', '2009-05-02 10:20:24.000000', NULL, 1),
(5463342, 786176, 105113, '<td valign="top">I like the strong shades. Good use of parallel lines.</td>', 'I like the strong shades. Good use of parallel lines.', '2009-05-02 10:20:38.000000', NULL, 1),
(5463348, 785419, 105113, '<td valign="top">I love the flowers. However, because they are such a large presence and you only have a small portion of the trunks of the trees it feels like the flowers are more your main subject.</td>', 'I love the flowers. However, because they are such a large presence and you only have a small portion of the trunks of the trees it feels like the flowers are more your main subject.', '2009-05-02 10:22:39.000000', NULL, 1),
(5463360, 786250, 105113, '<td valign="top">I love the colors in this picture. Though the title suggests otherwise, and the tree is off-set, the tree is the largest element in the picture suggesting it is your subject. Well done.</td>', 'I love the colors in this picture. Though the title suggests otherwise, and the tree is off-set, the tree is the largest element in the picture suggesting it is your subject. Well done.', '2009-05-02 10:26:32.000000', NULL, 1),
(5463373, 785112, 105113, '<td valign="top">The picture is framed by trees but I don''t see them as a subject matter in this picture. Lighting is also too flat for a stunning picture.</td>', 'The picture is framed by trees but I don''t see them as a subject matter in this picture. Lighting is also too flat for a stunning picture.', '2009-05-02 10:30:21.000000', NULL, 1),
(5463377, 786132, 105113, '<td valign="top">I do like the colours, and the clear division lines makes the trees stand out.</td>', 'I do like the colours, and the clear division lines makes the trees stand out.', '2009-05-02 10:31:47.000000', NULL, 1),
(5463385, 785483, 105113, '<td valign="top">I did not notice the apex of the mountain at first and was wondering why you had called it the redeemer tree. Now, that I notice it though, the picture takes on a whole new meaning. I think the picture would have worked better if you had taken a slightly different perspective, raising the cross higher into the light/opening of the tree.</td>', 'I did not notice the apex of the mountain at first and was wondering why you had called it the redeemer tree. Now, that I notice it though, the picture takes on a whole new meaning. I think the picture would have worked better if you had taken a slightly different perspective, raising the cross higher into the light/opening of the tree.', '2009-05-02 10:33:57.000000', NULL, 1),
(5463394, 786296, 105113, '<td valign="top">Lighting is too flat for a stunning picture.</td>', 'Lighting is too flat for a stunning picture.', '2009-05-02 10:36:32.000000', NULL, 1),
(5463396, 786244, 105113, '<td valign="top">I like the perspective and the simplicity of the picture. Well done.</td>', 'I like the perspective and the simplicity of the picture. Well done.', '2009-05-02 10:36:58.000000', NULL, 1),
(5463403, 785916, 105113, '<td valign="top">The conversion to black and white really makes this tree stand out. Cropped a little too close IMO</td>', 'The conversion to black and white really makes this tree stand out. Cropped a little too close IMO', '2009-05-02 10:38:55.000000', NULL, 1),
(5463405, 785007, 105113, '<td valign="top">Lighting is a bit flat to make this a stunning picture.</td>', 'Lighting is a bit flat to make this a stunning picture.', '2009-05-02 10:40:02.000000', NULL, 1),
(5463409, 785722, 105113, '<td valign="top">Nice perspective on a dead tree. The uniform coloring of the sky makes the tree stand out - nice.</td>', 'Nice perspective on a dead tree. The uniform coloring of the sky makes the tree stand out - nice.', '2009-05-02 10:40:31.000000', NULL, 1),
(5463411, 785965, 105113, '<td valign="top">The lightposts are distracting in this setting with many vertical trees.</td>', 'The lightposts are distracting in this setting with many vertical trees.', '2009-05-02 10:41:24.000000', NULL, 1),
(5463415, 786292, 105113, '<td valign="top">I like the uniform sway of the trees and how they are set in opposition of the city scape.</td>', 'I like the uniform sway of the trees and how they are set in opposition of the city scape.', '2009-05-02 10:41:54.000000', NULL, 1),
(5463417, 785001, 105113, '<td valign="top">Creative ides. A little too blurry, IMO.</td>', 'Creative ides. A little too blurry, IMO.', '2009-05-02 10:42:19.000000', NULL, 1),
