(5463929, 785977, 67258, '<td valign="top">Rather clever, and a very different take on the challenge.</td>', 'Rather clever, and a very different take on the challenge.', '2009-05-02 14:27:24.000000', NULL, 1),
(5463940, 786277, 67258, '<td valign="top">Without a doubt, my favourite of the challenge.  The composition is spot-on, the tonal range of the sunset is enhanced without becoming unrealistic.  Simply gorgeous.  The only thing I would alter is the slight lightening of the bakcground just above the water horizon, either side of the trunk.</td>', 'Without a doubt, my favourite of the challenge.  The composition is spot-on, the tonal range of the sunset is enhanced without becoming unrealistic.  Simply gorgeous.  The only thing I would alter is the slight lightening of the bakcground just above the water horizon, either side of the trunk.', '2009-05-02 14:40:23.000000', NULL, 1),
(5463941, 786284, 67258, '<td valign="top">Beautifully observed and amongst my top picks for the challenge.</td>', 'Beautifully observed and amongst my top picks for the challenge.', '2009-05-02 14:40:50.000000', NULL, 1),
(5463942, 786179, 67258, '<td valign="top">Very well done, and my favourite of the ''up to the skies'' take on the challenge.</td>', 'Very well done, and my favourite of the ''up to the skies'' take on the challenge.', '2009-05-02 14:41:30.000000', NULL, 1),
