(5467918, 785671, 103911, '<td valign="top">very cool</td>', 'very cool', '2009-05-04 13:48:26.000000', NULL, 1),
(5467941, 784872, 63499, '<td valign="top">Coming back to comment - I like your lighting and exposure. The sky has some cloud detail and isn''t too over exposed. I think the composition could be better if this was cropped just above the road, or if some of the sky was cropped out, as the tree is too centered vertically. It also looks like it''s very over sharpened.</td>', 'Coming back to comment - I like your lighting and exposure. The sky has some cloud detail and isn''t too over exposed. I think the composition could be better if this was cropped just above the road, or if some of the sky was cropped out, as the tree is too centered vertically. It also looks like it''s very over sharpened.', '2009-05-04 14:20:30.000000', NULL, 1),
(5467945, 786284, 63499, '<td valign="top">Coming back to comment - Unique way of having the tree in your photo. I like the use of shadows in this and nice lighting on the couple.</td>', 'Coming back to comment - Unique way of having the tree in your photo. I like the use of shadows in this and nice lighting on the couple.', '2009-05-04 14:25:26.000000', NULL, 1),
(5467948, 785701, 63499, '<td valign="top">Coming back to comment - I like the hazy look to this. I like the composition and the bird is a nice added bit of interest to the photo.</td>', 'Coming back to comment - I like the hazy look to this. I like the composition and the bird is a nice added bit of interest to the photo.', '2009-05-04 14:27:18.000000', NULL, 1),
(5467950, 786277, 63499, '<td valign="top">Nice colors and silhouette. There''s a strange halo around the tree right where it goes through the tree line in the background though.</td>', 'Nice colors and silhouette. There''s a strange halo around the tree right where it goes through the tree line in the background though.', '2009-05-04 14:27:57.000000', NULL, 1),
