(5476684, 785830, 31270, '<td valign="top">amazingly creative!</td>', 'amazingly creative!', '2009-05-08 12:00:50.000000', NULL, 0),
(5476876, 786066, 66384, '<td valign="top">This is an extraordinary photo. I can''t believe it didn''t get a much higher score. Beautiful shot to start with, and beautiful processing. The bird makes it special for me. There is such height and air to the image. The only thing I might suggest would be to crop off the windows at the bottom. I think they reduce that lofty feeling with too heavy an anchor.</td>', 'This is an extraordinary photo. I can''t believe it didn''t get a much higher score. Beautiful shot to start with, and beautiful processing. The bird makes it special for me. There is such height and air to the image. The only thing I might suggest would be to crop off the windows at the bottom. I think they reduce that lofty feeling with too heavy an anchor.', '2009-05-08 13:47:45.000000', NULL, 0),
(5476886, 786192, 66384, '<td valign="top">Is it my eyes, or is this out of focus? I really like your composition, and the colors and contrast are really nice. The mood of the swamp is well captured.</td>', 'Is it my eyes, or is this out of focus? I really like your composition, and the colors and contrast are really nice. The mood of the swamp is well captured.', '2009-05-08 13:52:52.000000', NULL, 0),
(5477352, 784771, 74559, '<td valign="top">So happy to see you ribbon, Steve, and congrats on the new PB!! I love the vibrant colors, your exposure is wonderful, and how cool that you continue to image this worthy subject :-)</td>', 'So happy to see you ribbon, Steve, and congrats on the new PB!! I love the vibrant colors, your exposure is wonderful, and how cool that you continue to image this worthy subject :-)', '2009-05-08 19:02:48.000000', NULL, 0),
(5477669, 784771, 63244, '<td valign="top">Steve! You crazy Texan you...congrats on  your ribbon!!!  :)   This is a beautiful shot and you''ve done a fantastic job on the colors! Well deserved ribbon!!</td>', 'Steve! You crazy Texan you...congrats on  your ribbon!!!  :)   This is a beautiful shot and you''ve done a fantastic job on the colors! Well deserved ribbon!!', '2009-05-09 00:19:02.000000', NULL, 0),
(5478292, 784771, 102024, '<td valign="top">Congrats on your first ribbon and a great shot!</td>', 'Congrats on your first ribbon and a great shot!', '2009-05-09 14:35:03.000000', NULL, 0),
(5478305, 785688, 83313, '<td valign="top">Voting has gotten harsher of late. Your average on this is a good score in my book. This did not come up for me in voting but I think I would have probably given it a 7. At least a 6. I agree that you tossed just the right amount of Topaz at it. It picked up some wonderful detail of the lightplay on the tree trunk without making it look totally unrealistic.<br/> <br/>Would be nice to hear feedback from some of the low voters occasionally.</td>', 'Voting has gotten harsher of late. Your average on this is a good score in my book. This did not come up for me in voting but I think I would have probably given it a 7. At least a 6. I agree that you tossed just the right amount of Topaz at it. It picked up some wonderful detail of the lightplay on the tree trunk without making it look totally unrealistic. Would be nice to hear feedback from some of the low voters occasionally.', '2009-05-09 14:53:36.000000', NULL, 0),
(5478646, 785496, 50695, '<td valign="top">very nice, hippie. I could easily see this in a lit mag.</td>', 'very nice, hippie. I could easily see this in a lit mag.', '2009-05-09 21:28:41.000000', NULL, 0),
(5478647, 785822, 50695, '<td valign="top">that is really cool!!</td>', 'that is really cool!!', '2009-05-09 21:29:09.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5478649, 785652, 50695, '<td valign="top">not boring. I like it a lot. a great composition with the subject moving toward the center. It reminds me of a chess game. Where you are is not important, it''s where you''re going...</td>', 'not boring. I like it a lot. a great composition with the subject moving toward the center. It reminds me of a chess game. Where you are is not important, it''s where you''re going...', '2009-05-09 21:30:26.000000', NULL, 0),
(5479231, 786054, 59267, '<td valign="top">Very strong perspective, lighting and colors. Congratulations to your blue ribbon on bluebell!!</td>', 'Very strong perspective, lighting and colors. Congratulations to your blue ribbon on bluebell!!', '2009-05-10 13:26:03.000000', NULL, 0),
(5479232, 784771, 59267, '<td valign="top">Congratulations on your ribbon and PB!!</td>', 'Congratulations on your ribbon and PB!!', '2009-05-10 13:27:41.000000', NULL, 0),
(5479235, 785701, 59267, '<td valign="top">Nice shot. Congratulations on your ribbon!! Good performance within 2 challenges.</td>', 'Nice shot. Congratulations on your ribbon!! Good performance within 2 challenges.', '2009-05-10 13:29:47.000000', NULL, 0),
(5479471, 785160, 59029, '<td valign="top">Greetings from the Critique Club!<br/> <br/>Initial impression: Wow, very nicely done and in very tough lighting conditions.  Slightly dreamy feel adds to the impact.<br/> <br/>Technical: Composition and dof great, lighting ambient, some beams and reflection off water are a little glarey.  Smaller aperture would have helped.  Shows off tree very well, like the way your subject also helps frame the light showing it to advantage.<br/> <br/>Artistic: ''shot at sunrise''....that says it all. Great soft glow, and love the explanation of the smoke! :-)<br/> <br/>FWIW: Looks like you went and saw your shot, set your alarm for 4am and went and did it.  Good for you!  I admire that kind of dedication.  Apart from a smaller aperture I might have cropped it at the bottom a little.  Not surprised you finished in the top 10.  Keep up the great work!<br/> <br/>Feel free to PM me with any questions,<br/> <br/>Susan<br/></td>', 'Greetings from the Critique Club! Initial impression: Wow, very nicely done and in very tough lighting conditions.  Slightly dreamy feel adds to the impact. Technical: Composition and dof great, lighting ambient, some beams and reflection off water are a little glarey.  Smaller aperture would have helped.  Shows off tree very well, like the way your subject also helps frame the light showing it to advantage. Artistic: ''shot at sunrise''....that says it all. Great soft glow, and love the explanation of the smoke! :-) FWIW: Looks like you went and saw your shot, set your alarm for 4am and went and did it.  Good for you!  I admire that kind of dedication.  Apart from a smaller aperture I might have cropped it at the bottom a little.  Not surprised you finished in the top 10.  Keep up the great work! Feel free to PM me with any questions, Susan', '2009-05-10 18:08:57.000000', NULL, 0),
(5479598, 786244, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>there is a yearning in this image, a reaching, that really works</td>', 'PostLuminous Award Nominee!there is a yearning in this image, a reaching, that really works', '2009-05-10 21:18:57.000000', NULL, 0),
(5479600, 786066, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>What a GREAT shot!!  A wonderfully out of the box approach to this challenge, but forget this challenge--this image stands on its own merits and needs neither votes or postlumie awards to validate it... :-)</td>', 'PostLuminous Award Nominee!What a GREAT shot!!  A wonderfully out of the box approach to this challenge, but forget this challenge--this image stands on its own merits and needs neither votes or postlumie awards to validate it... :-)', '2009-05-10 21:20:43.000000', NULL, 0),
(5479603, 785652, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/> <br/>I really like this image, and not just because it lets me use the word "juxtaposition" so I can seem all smart ''n'' stuff....<br/>Very well seen, well executed!</td>', 'PostLuminous Award Nominee! I really like this image, and not just because it lets me use the word "juxtaposition" so I can seem all smart ''n'' stuff....Very well seen, well executed!', '2009-05-10 21:22:12.000000', NULL, 0),
(5479606, 785822, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>surreal and dreamlike--and a good image as well.  Nicely done.</td>', 'PostLuminous Award Nominee!surreal and dreamlike--and a good image as well.  Nicely done.', '2009-05-10 21:23:04.000000', NULL, 0),
(5479610, 786284, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677021" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677021.jpg"/></a>PostLuminous Award Nominee!<br/>Well, this, for me, is an example of why I love photography.  This has the mood, the composition, the lighting, the technique, but more than all of that, at first sight of this image there is absolutely no question "why" you pressed the shutter release.  I think this particular challenge was not worthy of this entry--this is, to me, a fine art image.<br/> <br/></td>', 'PostLuminous Award Nominee!Well, this, for me, is an example of why I love photography.  This has the mood, the composition, the lighting, the technique, but more than all of that, at first sight of this image there is absolutely no question "why" you pressed the shutter release.  I think this particular challenge was not worthy of this entry--this is, to me, a fine art image. ', '2009-05-10 21:27:34.000000', NULL, 0),
(5479639, 786290, 82985, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=677020" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/80000-84999/82985/120/677020.jpg"/></a>PostLuminous Award WINNER!<br/>A fantastic entry in the challenge, but also a great image independent of the challenge.  Well Done.</td>', 'PostLuminous Award WINNER!A fantastic entry in the challenge, but also a great image independent of the challenge.  Well Done.', '2009-05-10 21:51:45.000000', NULL, 0),
